#include <stdio.h>
int main() {
    char n1[100], n2[100]; long long b1, b2, b3;
    if (scanf("%s %s %lld %lld %lld", n1, n2, &b1, &b2, &b3) != 5) return 0;
    long long v1 = 0, v2 = 0;
    for (int i = 0; n1[i]; i++) v1 = v1 * b1 + (n1[i] - '0');
    for (int i = 0; n2[i]; i++) v2 = v2 * b2 + (n2[i] - '0');
    long long total = v1 + v2;
    if (total == 0) { printf("0\n"); return 0; }
    char digits[100]; int idx = 0;
    while (total > 0) { digits[idx++] = (total % b3) + '0'; total /= b3; }
    for (int i = idx - 1; i >= 0; i--) putchar(digits[i]);
    putchar('\n');
    return 0;
}

