import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String n1 = sc.next(), n2 = sc.next();
            long b1 = sc.nextLong(), b2 = sc.nextLong(), b3 = sc.nextLong();
            long v1 = 0, v2 = 0;
            for (char c : n1.toCharArray()) v1 = v1 * b1 + (c - '0');
            for (char c : n2.toCharArray()) v2 = v2 * b2 + (c - '0');
            long total = v1 + v2;
            if (total == 0) { System.out.println("0"); return; }
            StringBuilder sb = new StringBuilder();
            while (total > 0) { sb.append(total % b3); total /= b3; }
            System.out.println(sb.reverse().toString());
        }
    }
}

